// R115: registry-order default (id ascending) — identical to the core browse
// view and every other skin, so the same dataset reads in the same order.
const EMPTY_PARAMS: RegistryBrowseParams = { sort: "id", dir: "asc", limit: 25, offset: 0 };
const roleLabel = (role: string, locale: "en"|"fa"|"ar") => { const map: Record<string,[string,string]> = { owner:["Owner","مالک"], breeder:["Breeder","پرورش‌دهنده"], importer:["Importer","واردکننده"], passport_receiver:["Passport receiver","گیرنده گذرنامه"] }; const pair = map[role]; return pair ? t(locale, pair[0], pair[1]) : role; };
const boolFilterValue=(value:boolean|undefined)=>value===true?"1":value===false?"0":"";
const parseBoolFilter=(value:string):boolean|undefined=>value==="1"?true:value==="0"?false:undefined;

export function HomePage({ view, goLocal }: { view: ClassicRuntime; goLocal: (path:string)=>void }) {
  const L=(en:string,fa:string)=>t(view.locale,en,fa);
  const stats=view.platformMeta?.stats;
  const links=[
    {label:L("HORSES","اسب‌ها"),detail:L(`${num(stats?.horses,view.locale)} horse records are available to search and explore.`,`${num(stats?.horses,view.locale)} پرونده اسب برای جست‌وجو و بررسی در دسترس است.`),go:()=>view.navigate(horseDbRoutes.browse())},
    {label:L("PERSONS","افراد"),detail:L("Find people linked to recorded ownership, breeding, import and passport information.","افراد مرتبط با اطلاعات ثبت‌شده مالکیت، پرورش، واردات و گذرنامه را پیدا کنید."),go:()=>goLocal("/people")},
    {label:L("PEDIGREE & RELATIONSHIPS","تبارنامه و خویشاوندی"),detail:L("Ancestors, descendants, paths, coefficients and relationship intelligence are available where supported.","نیاکان، نوادگان، مسیرها، ضرایب و هوشمندی خویشاوندی در صورت پشتیبانی در دسترس‌اند."),go:()=>goLocal("/pedigree")},
    {label:L("REGISTRY ANALYTICS","تحلیل سامانه ثبت"),detail:L("Population, provenance, timeline and registry intelligence use live Horse DB data.","جمعیت، منشأ، خط زمانی و تحلیل سامانه ثبت از داده زنده Horse DB استفاده می‌کنند."),go:()=>view.navigate(horseDbRoutes.stats())},
    {label:L("DATA QUALITY","کیفیت داده"),detail:L("Review missing information and records that need attention.","اطلاعات ناقص و پرونده‌های نیازمند بررسی را مشاهده کنید."),go:()=>goLocal(view.capabilities.quality?"/quality":"/platform")},
    {label:L("NEWS / UPDATES","اخبار / به‌روزرسانی"),detail:L("Read published registry notices and articles in English and Persian.","اطلاعیه‌ها و مقاله‌های منتشرشده سامانه را به فارسی و انگلیسی بخوانید."),go:()=>goLocal("/content")},
  ];
  return <main className="fc-main fei-home-page"><div className="fei-home-grid fei-home-grid-classic"><div className="fei-home-copy">
    <h1 className="fei-section-heading">{L("WELCOME TO THE HORSE REGISTRY","به سامانه ثبت اسب خوش آمدید")}</h1>
    <p className="fei-home-intro">{L("Search horse records, explore pedigrees and follow your registry requests in one place. Choose a section below to begin.","پرونده اسب‌ها را جست‌وجو کنید، تبار آن‌ها را بررسی کنید و درخواست‌های ثبت را در یک‌جا پیگیری کنید. برای شروع، یکی از بخش‌های زیر را انتخاب کنید.")}</p>
    <div className="fei-home-feature-list">{links.map(item=><p key={item.label}><button className="fei-inline-classic-link" onClick={item.go}>{item.label}:</button> {item.detail}</p>)}</div>
    <DonorSectionHeading>{L("ACCESS TO HORSE DB TOOLS","دسترسی به ابزارهای HORSE DB")}</DonorSectionHeading>
    <p>{L("Use the navigation to explore records, compare ancestry and follow your requests. Account actions appear according to your access.","از منو برای بررسی پرونده‌ها، مقایسه تبار و پیگیری درخواست‌ها استفاده کنید. اقدامات حساب با توجه به سطح دسترسی شما نمایش داده می‌شوند.")}</p>
    <ul className="fei-home-classic-list"><li>{L("Horse records and detailed search","پرونده اسب‌ها و جست‌وجوی پیشرفته")}</li><li>{L("Pedigree and relationship intelligence","تحلیل تبارنامه و خویشاوندی")}</li><li>{L("Registry analytics and quality","تحلیل سامانه ثبت و کیفیت")}</li><li>{L("Ownership requests and record corrections","درخواست مالکیت و اصلاح پرونده")}</li><li>{L("Bilingual content and administration","محتوا و مدیریت دوزبانه")}</li></ul>
    <p>{L("To begin, choose a section from the menu above. All displayed registry data comes from the active Horse DB backend.","برای شروع، بخشی را از منوی بالا انتخاب کنید. تمام داده‌های سامانه ثبت نمایش‌داده‌شده از سرویس فعال Horse DB می‌آیند.")}</p>
    <footer className="fei-home-inline-footer">{L("Should you need any more information, please use the registry navigation above.","برای اطلاعات بیشتر از پیمایش سامانه ثبت در بالا استفاده کنید.")}<br/>©2026 · Horse DB · Federation Classic</footer>
  </div><aside className="fei-home-standings" aria-label={L("Explore the registry", "کاوش سامانه ثبت")}><DonorSectionHeading>{L("EXPLORE THE REGISTRY","بخش‌های سامانه ثبت")}</DonorSectionHeading><div className="fei-donor-ranking-visual"><img src="/assets/frontends/fei-classic/donor-ranking.webp" alt="" aria-hidden="true"/><div className="fei-donor-ranking-hotspots" role="navigation" aria-label={L("Registry navigation shortcuts","میان‌برهای پیمایش سامانه ثبت")}><button onClick={()=>view.navigate(horseDbRoutes.browse())} aria-label={L("Horses","اسب‌ها")}><span>{L("Horses","اسب‌ها")}</span></button><button onClick={()=>goLocal("/pedigree")} aria-label={L("Pedigree","تبارنامه")}><span>{L("Pedigree","تبارنامه")}</span></button><button onClick={()=>goLocal("/people")} aria-label={L("People","افراد")}><span>{L("People","افراد")}</span></button><button onClick={()=>view.navigate(horseDbRoutes.stats())} aria-label={L("Analytics","تحلیل")}><span>{L("Analytics","تحلیل")}</span></button><button onClick={()=>goLocal(view.capabilities.quality?"/quality":"/platform")} aria-label={L("Quality","کیفیت")}><span>{L("Quality","کیفیت")}</span></button><button onClick={()=>goLocal("/breeding")} aria-label={L("Breeding","جفت‌گیری")}><span>{L("Breeding","جفت‌گیری")}</span></button><button onClick={()=>goLocal("/rankings")} aria-label={L("Intelligence","هوشمندی")}><span>{L("Intelligence","هوشمندی")}</span></button><button onClick={()=>goLocal("/content")} aria-label={L("News","اخبار")}><span>{L("News","اخبار")}</span></button></div></div></aside></div></main>;
}

export function RegistryPage({view}:{view:ClassicRuntime}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa); const [params,setParams]=useState<RegistryBrowseParams>(EMPTY_PARAMS); const [draft,setDraft]=useState<RegistryBrowseParams>(EMPTY_PARAMS);
  const rows=useAsync(signal=>view.platform.registry.browse(params,{signal}),[view.platform,JSON.stringify(params)]);
  const facets=useAsync(signal=>view.platform.registry.facets({signal}),[view.platform],view.capabilities.facets);
  const searchMeta=useAsync(signal=>view.platform.search.meta({signal}),[view.platform]);
  const apply=(e?:FormEvent)=>{e?.preventDefault();setParams({...draft,offset:0,limit:draft.limit??25})}; const reset=()=>{setDraft(EMPTY_PARAMS);setParams(EMPTY_PARAMS)};
  const exportParams=useMemo(()=>{const {limit:_l,offset:_o,...rest}=params;return rest},[params]); const canExport=view.capabilities.exports&&view.permissions.includes("registry.export");
  const exportCsv=canExport?view.platform.exports.registry(exportParams,"csv"):null; const exportJson=canExport?view.platform.exports.registry(exportParams,"json"):null; const f=facets.data;
  const sortBy=(sort:RegistryBrowseParams["sort"])=>{if(!sort)return;const dir=params.sort===sort&&params.dir==="asc"?"desc":"asc";setParams({...params,sort,dir,offset:0});setDraft({...draft,sort,dir})};
  const sortMark=(sort:RegistryBrowseParams["sort"])=>params.sort===sort?(params.dir==="desc"?" ▼":" ▲"):"";
  const page=rows.data?Math.floor(rows.data.offset/Math.max(1,rows.data.limit))+1:1;
  return <main className="fc-main fei-fade-in"><PageTitle title={L("Horse Search","جست‌وجوی اسب")} subtitle={L("Find horses by name, registration number or other recorded details.","اسب‌ها را بر اساس نام، شماره ثبت یا سایر مشخصات پیدا کنید.")}/>
    {f?.snapshotStale&&<div className="fc-alert">{L("Derived facet snapshot is stale; the platform is serving an exact live fallback for authoritative results.","آمار ذخیره‌شده به‌روز نیست. گزینه‌های جست‌وجو مستقیماً از اطلاعات فعلی محاسبه می‌شوند.")}</div>}
    <form onSubmit={apply} className="fei-search-form-stack">
      <DonorPanel className="fei-search-panel"><div className="fei-donor-grid two"><DonorField label={L("Name","نام")} info={L("Current canonical horse name","نام ثبت‌شده اسب")}><input className="fei-input" value={String(draft.name??"")} onChange={e=>setDraft({...draft,name:e.target.value})} dir="auto"/></DonorField><DonorField label={L("Horse ID","شناسه اسب")} info={L("Exact canonical numeric ID","شناسه عددی اسب در این سامانه")}><input className="fei-input" inputMode="numeric" value={String(draft.id??"")} onChange={e=>setDraft({...draft,id:e.target.value||undefined})}/></DonorField><DonorField label={L("Registry no.","شماره ثبت")} info={L("Canonical registry identifier","شناسه مرجع سامانه ثبت")}><input className="fei-input" value={String(draft.register??"")} onChange={e=>setDraft({...draft,register:e.target.value})} dir="ltr"/></DonorField><DonorField label={L("Any text","متن آزاد")} info={L("Searchable canonical fields","فیلدهای مرجع قابل جست‌وجو")}><input className="fei-input" value={String(draft.q??"")} onChange={e=>setDraft({...draft,q:e.target.value})} dir="auto"/></DonorField></div></DonorPanel>
      <details className="fei-advanced-search">
        <summary>
          <span className="fei-advanced-title">{L("Advanced search filters","فیلترهای جست‌وجوی پیشرفته")}</span>
          <small>{L("Breed, colour, people, flags and more","نژاد، رنگ، مالک، والدین و سایر مشخصات")}</small>
          <span className="fei-advanced-caret" aria-hidden="true"/>
        </summary>
      <DonorPanel className="fei-search-panel"><div className="fei-donor-grid three"><DonorField label={L("Sex","جنسیت")}><select className="fei-select" value={String(draft.sex??"")} onChange={e=>setDraft({...draft,sex:e.target.value||undefined})}><option value="">{L("All","همه")}</option>{f?.sexes.map(x=><option key={x.value} value={x.value}>{horseSexLabel(x.value,view.locale)}</option>)}</select></DonorField><DonorField label={L("Lifecycle","وضعیت حیات")}><select className="fei-select" value={String(draft.lifecycle??"")} onChange={e=>setDraft({...draft,lifecycle:e.target.value||undefined})}><option value="">{L("All","همه")}</option><option value="active">{L("Active","فعال")}</option><option value="inactive">{L("Inactive","غیرفعال")}</option><option value="deceased">{L("Deceased","تلف‌شده")}</option></select></DonorField><DonorField label={L("Breed","نژاد")}><select className="fei-select" value={String(draft.breed??"")} onChange={e=>setDraft({...draft,breed:e.target.value||undefined})}><option value="">{L("All","همه")}</option>{f?.breeds.slice(0,100).map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></DonorField><DonorField label={L("Color","رنگ")}><select className="fei-select" value={String(draft.color??"")} onChange={e=>setDraft({...draft,color:e.target.value||undefined})}><option value="">{L("All","همه")}</option>{f?.colors.slice(0,100).map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></DonorField><DonorField label={L("Main strain","تیره اصلی")}><select className="fei-select" value={String(draft.mainStrain??"")} onChange={e=>setDraft({...draft,mainStrain:e.target.value||undefined})}><option value="">{L("All","همه")}</option>{f?.mainStrains.slice(0,100).map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></DonorField><DonorField label={L("Birth place","محل تولد")}><select className="fei-select" value={String(draft.place??"")} onChange={e=>setDraft({...draft,place:e.target.value||undefined})}><option value="">{L("All","همه")}</option>{f?.places.slice(0,100).map(x=><option key={x.value} value={x.value}>{x.value}</option>)}</select></DonorField><DonorField label={L("Imported from","مبدأ واردات")}><select className="fei-select" value={String(draft.importedFrom??"")} onChange={e=>setDraft({...draft,importedFrom:e.target.value||undefined})}><option value="">{L("All","همه")}</option>{f?.importedFrom.slice(0,100).map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></DonorField><DonorField label={L("Year from","سال از")}><input className="fei-input" inputMode="numeric" value={String(draft.yearFrom??"")} onChange={e=>setDraft({...draft,yearFrom:e.target.value||undefined})}/></DonorField><DonorField label={L("Year to","سال تا")}><input className="fei-input" inputMode="numeric" value={String(draft.yearTo??"")} onChange={e=>setDraft({...draft,yearTo:e.target.value||undefined})}/></DonorField></div></DonorPanel>
      <DonorPanel className="fei-search-panel"><div className="fei-donor-grid three"><DonorField label={L("Owner","مالک")}><input className="fei-input" value={String(draft.owner??"")} onChange={e=>setDraft({...draft,owner:e.target.value})} dir="auto"/></DonorField><DonorField label={L("Owner ID","شناسه مالک")}><input className="fei-input" inputMode="numeric" value={String(draft.ownerId??"")} onChange={e=>setDraft({...draft,ownerId:e.target.value?Number(e.target.value):undefined})}/></DonorField><DonorField label={L("Breeder","پرورش‌دهنده")}><input className="fei-input" value={String(draft.breeder??"")} onChange={e=>setDraft({...draft,breeder:e.target.value})} dir="auto"/></DonorField><DonorField label={L("Breeder ID","شناسه پرورش‌دهنده")}><input className="fei-input" inputMode="numeric" value={String(draft.breederId??"")} onChange={e=>setDraft({...draft,breederId:e.target.value?Number(e.target.value):undefined})}/></DonorField><DonorField label={L("Importer","واردکننده")}><input className="fei-input" value={String(draft.importer??"")} onChange={e=>setDraft({...draft,importer:e.target.value})} dir="auto"/></DonorField><DonorField label={L("Passport receiver","گیرنده گذرنامه")}><input className="fei-input" value={String(draft.passportReceiver??"")} onChange={e=>setDraft({...draft,passportReceiver:e.target.value})} dir="auto"/></DonorField><DonorField label={L("Sire name","نام پدر")}><input className="fei-input" value={String(draft.sire??"")} onChange={e=>setDraft({...draft,sire:e.target.value})} dir="auto"/></DonorField><DonorField label={L("Dam name","نام مادر")}><input className="fei-input" value={String(draft.dam??"")} onChange={e=>setDraft({...draft,dam:e.target.value})} dir="auto"/></DonorField></div></DonorPanel>
      <DonorPanel className="fei-search-panel"><div className="fei-donor-grid three"><DonorField label={L("Has sire","پدر ثبت‌شده")}><select className="fei-select" value={boolFilterValue(draft.hasSire)} onChange={e=>setDraft({...draft,hasSire:parseBoolFilter(e.target.value)})}><option value="">{L("All","همه")}</option><option value="1">{L("Yes","بله")}</option><option value="0">{L("No","خیر")}</option></select></DonorField><DonorField label={L("Has dam","مادر ثبت‌شده")}><select className="fei-select" value={boolFilterValue(draft.hasDam)} onChange={e=>setDraft({...draft,hasDam:parseBoolFilter(e.target.value)})}><option value="">{L("All","همه")}</option><option value="1">{L("Yes","بله")}</option><option value="0">{L("No","خیر")}</option></select></DonorField><DonorField label={L("Imported","وارداتی")}><select className="fei-select" value={boolFilterValue(draft.isImported)} onChange={e=>setDraft({...draft,isImported:parseBoolFilter(e.target.value)})}><option value="">{L("All","همه")}</option><option value="1">{L("Yes","بله")}</option><option value="0">{L("No","خیر")}</option></select></DonorField><DonorField label={L("Sport horse","اسب ورزشی")}><select className="fei-select" value={boolFilterValue(draft.isSport)} onChange={e=>setDraft({...draft,isSport:parseBoolFilter(e.target.value)})}><option value="">{L("All","همه")}</option><option value="1">{L("Yes","بله")}</option><option value="0">{L("No","خیر")}</option></select></DonorField><DonorField label={L("Stallion flag","ثبت‌شده به‌عنوان نریان")}><select className="fei-select" value={boolFilterValue(draft.isStallion)} onChange={e=>setDraft({...draft,isStallion:parseBoolFilter(e.target.value)})}><option value="">{L("All","همه")}</option><option value="1">{L("Yes","بله")}</option><option value="0">{L("No","خیر")}</option></select></DonorField><DonorField label={L("Sport card","کارت ورزشی")}><select className="fei-select" value={boolFilterValue(draft.hasSportCard)} onChange={e=>setDraft({...draft,hasSportCard:parseBoolFilter(e.target.value)})}><option value="">{L("All","همه")}</option><option value="1">{L("Yes","بله")}</option><option value="0">{L("No","خیر")}</option></select></DonorField></div></DonorPanel>
      </details>
      <div className="fei-search-actions"><div>{canExport&&<><a className="fc-btn fc-btn-purple" href={exportCsv!.href} download={exportCsv!.filename}><Icon name="download"/>CSV</a><a className="fc-btn fc-btn-purple" href={exportJson!.href} download={exportJson!.filename}><Icon name="download"/>JSON</a></>}{view.capabilities.exports&&!canExport&&<span className="fc-permission-note">{L("Export requires registry.export permission.","خروجی به مجوز registry.export نیاز دارد.")}</span>}</div><DonorSearchButtons onReset={reset} onSearch={()=>apply()} loading={rows.status==="loading"} searchLabel={L("Search","جست‌وجو")} resetLabel={L("Reset","پاک کردن")}/></div>
    </form>
    {searchMeta.data&&<details className="fc-details fei-search-help"><summary>{L("Search syntax & searchable fields","راهنمای جست‌وجوی پیشرفته")}</summary><div className="fc-status-strip"><span><b>{L("Syntax version","نسخه نحو")}</b> <bdi>{searchMeta.data.syntaxVersion}</bdi></span><span><b>{L("Maximum query length","حداکثر طول عبارت جست‌وجو")}</b> {num(searchMeta.data.maxQueryLength,view.locale)}</span><span><b>{L("Structured combinator","شیوه ترکیب شرط‌ها")}</b> {searchMeta.data.registryFieldSearch.combinator.toUpperCase()}</span></div><div className="fc-admin-ledger-grid">{searchMeta.data.fields.map(field=><div key={field.key}><b>{field.key}</b><span dir="auto">{field.aliases.join(", ")||"—"}</span></div>)}{searchMeta.data.registryFieldSearch.fields.map(field=><div key={`registry-${field.key}`}><b>{field.key}</b><span><bdi>{field.queryParam}</bdi> · {field.type}</span></div>)}</div></details>}
    {searchMeta.status==="error"&&<div className="fc-alert fc-alert-danger" dir="auto">{L("Search metadata could not be loaded:","فراداده جست‌وجو بارگذاری نشد:")} {searchMeta.error}</div>}
    <DonorPanel className="fei-results-panel"><div className="fei-results-head"><span>{L("Search results","نتایج جست‌وجو")}</span>{rows.data&&<strong>{num(rows.data.total,view.locale)} {L("records","رکورد")}</strong>}</div>{rows.status==="loading"&&!rows.data?<StatePanel status="loading" locale={view.locale}/>:rows.status==="error"?<StatePanel status="error" error={rows.error} locale={view.locale}/>:rows.data&&rows.data.rows.length?<><DonorPager total={rows.data.total} unit={L("Horse","اسب")} page={page} perPage={rows.data.limit} onPage={p=>setParams({...params,offset:(p-1)*rows.data!.limit})} onPerPage={n=>{setParams({...params,limit:n,offset:0});setDraft({...draft,limit:n})}} locale={view.locale}/><div className="fc-table-wrap"><table className="fc-table"><thead><tr><th><button className="fei-sort-button" onClick={()=>sortBy("id")}>ID{sortMark("id")}</button></th><th><button className="fei-sort-button" onClick={()=>sortBy("name")}>{L("Horse","اسب")}{sortMark("name")}</button></th><th>{L("Registry","ثبت")}</th><th><button className="fei-sort-button" onClick={()=>sortBy("sex")}>{L("Sex","جنس")}{sortMark("sex")}</button></th><th><button className="fei-sort-button" onClick={()=>sortBy("breed")}>{L("Breed","نژاد")}{sortMark("breed")}</button></th><th><button className="fei-sort-button" onClick={()=>sortBy("year")}>{L("Year","سال")}{sortMark("year")}</button></th><th><button className="fei-sort-button" onClick={()=>sortBy("place")}>{L("Place","محل")}{sortMark("place")}</button></th><th>{L("Parentage","والدین")}</th><th>{L("Visible coverage","پوشش قابل‌مشاهده")}</th></tr></thead><tbody>{rows.data.rows.map(h=><HorseRow key={h.id} horse={h} locale={view.locale} onOpen={()=>view.navigate(horseDbRoutes.horse(h.id))}/>)}</tbody></table></div><DonorPager total={rows.data.total} unit={L("Horse","اسب")} page={page} perPage={rows.data.limit} onPage={p=>setParams({...params,offset:(p-1)*rows.data!.limit})} locale={view.locale} compact/></>:<StatePanel status="ready" empty={L("No horses match these criteria.","هیچ اسبی با این معیارها یافت نشد.")} locale={view.locale}/>}</DonorPanel>
  </main>;
}
export function HorsePage({view,id,goLocal}:{view:ClassicRuntime;id:number;goLocal:(p:string)=>void}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa); const [tab,setTab]=useState("registry"); const data=useAsync(async signal=>{
    const profile=await view.platform.horses.get(id,{signal});
    const [metrics,insights]=await Promise.all([
      view.capabilities.metrics?view.platform.pedigree.metrics(id,{depth:6},{signal}).catch(()=>null):Promise.resolve(null),
      view.capabilities.insights?view.platform.analytics.horseInsights(id,{ancestorDepth:6,descendantDepth:4,metricsDepth:6,coefficientDepth:6},{signal}).catch(()=>null):Promise.resolve(null),
    ]);return{profile,metrics,insights};
  },[view.platform,id,view.capabilities.metrics,view.capabilities.insights]);
  if(data.status==="loading"&&!data.data)return <main className="fc-main"><StatePanel status="loading" locale={view.locale}/></main>; if(data.status==="error"||!data.data)return <main className="fc-main"><StatePanel status="error" error={data.error} locale={view.locale}/></main>;
  const {profile,metrics,insights}=data.data; const h=profile.horse; const groups=horseFieldsByGroup(h,{includeEmpty:true}); const canClaim=view.capabilities.claims&&Boolean(view.user)&&view.permissions.includes("claim.create");
  return <main className="fc-main fei-fade-in fei-profile-page"><PageTitle title={horseName(h,view.locale)} subtitle={`${L("Horse record","رکورد اسب")} · #${h.id}`} action={<div className="fc-title-buttons"><button className="fc-btn fc-btn-purple" onClick={()=>goLocal(`/pedigree/${id}`)}><Icon name="tree"/>{L("Pedigree","تبارنامه")}</button>{canClaim&&<a className="fc-btn fc-btn-orange" href="#fc-horse-claim-form">{L("Ownership claim","ادعای مالکیت")}</a>}</div>}/>
    <div className="fc-profile-head"><div className="fc-profile-symbol"><Icon name="horse"/></div><div><div className="fc-bilingual"><h2 dir="auto">{h.name_latin||h.name_native}</h2>{h.name_native&&h.name_latin&&<p dir="auto">{h.name_native}</p>}</div><HorseStatusBadges horse={h} locale={view.locale}/></div><dl><div><dt>{L("Registry no.","شماره ثبت")}</dt><dd><bdi>{h.register_no||"—"}</bdi></dd></div><div><dt>{L("Birth year","سال تولد")}</dt><dd>{year(h.birth_year,view.locale)}</dd></div><div><dt>{L("Breed","نژاد")}</dt><dd>{h.breed_desc||"—"}</dd></div><div><dt>{L("Sex","جنسیت")}</dt><dd>{h.sex_desc?<SexChip sex={h.sex_desc} locale={view.locale}/>:"—"}</dd></div></dl></div>
    <FeiHorseClaimPanel view={view} horseId={id}/>
    <div className="fc-parent-cards"><button className="fc-parent-card sire" disabled={!h.father_id} onClick={()=>h.father_id&&view.navigate(horseDbRoutes.horse(h.father_id))}><span>{L("SIRE / FATHER","پدر")}</span><strong dir="auto">{view.locale==="fa"?(h.father_name_native||h.father_name||L("Not recorded","ثبت نشده")):(h.father_name||h.father_name_native||L("Not recorded","ثبت نشده"))}</strong>{h.father_name&&h.father_name_native&&<em dir="auto">{view.locale==="fa"?h.father_name:h.father_name_native}</em>}{h.father_id&&<small>#{h.father_id}</small>}</button><button className="fc-parent-card dam" disabled={!h.mother_id} onClick={()=>h.mother_id&&view.navigate(horseDbRoutes.horse(h.mother_id))}><span>{L("DAM / MOTHER","مادر")}</span><strong dir="auto">{view.locale==="fa"?(h.mother_name_native||h.mother_name||L("Not recorded","ثبت نشده")):(h.mother_name||h.mother_name_native||L("Not recorded","ثبت نشده"))}</strong>{h.mother_name&&h.mother_name_native&&<em dir="auto">{view.locale==="fa"?h.mother_name:h.mother_name_native}</em>}{h.mother_id&&<small>#{h.mother_id}</small>}</button></div>
    <DonorTabs locale={view.locale} tabs={[{key:"registry",label:L("Registry details","جزئیات سامانه ثبت")},{key:"associations",label:L("People & aliases","افراد و نام‌ها")},{key:"intelligence",label:L("Pedigree intelligence","تحلیل تبارنامه")},{key:"records",label:L("Records","رکوردها")}] } active={tab} onChange={setTab}/><div className="fei-profile-tab-panel">
    {tab==="registry"&&<Section title={L("Registry fields","فیلدهای سامانه ثبت")}><div className="fc-field-groups">{Object.entries(groups).map(([group,fields])=>fields.length>0&&<div key={group}><h3>{group}</h3><dl>{fields.map(field=><div key={String(field.key)}><dt>{pick(field.label, view.locale)}</dt><dd dir="auto">{field.value===1?L("Yes","بله"):field.value===0?L("No","خیر"):String(field.value??"—")}</dd></div>)}</dl></div>)}</div></Section>}
    {tab==="associations"&&<Section title={L("People & aliases","افراد و نام‌های جایگزین")}><RelationshipSnapshot horse={h} view={view}/><h3 className="fc-subhead">{L("Registry associations","ارتباطات سامانه ثبت")}</h3>{profile.people.length?<div className="fc-person-links">{profile.people.map((p,i)=><button key={`${p.role}-${p.id}-${i}`} onClick={()=>view.navigate(horseDbRoutes.person(p.id))}><Badge tone="purple">{roleLabel(p.role,view.locale)}</Badge><strong dir="auto">{view.locale==="fa"?p.name_native||p.name_latin:p.name_latin||p.name_native}</strong>{p.is_current===1&&<Badge tone="active">{L("Current","فعلی")}</Badge>}</button>)}</div>:<p className="fc-muted">{L("No public person links recorded.","هیچ ارتباط عمومی با افراد ثبت نشده است.")}</p>}<h3 className="fc-subhead">{L("Aliases","نام‌های جایگزین")}</h3>{profile.aliases.length?<ul className="fc-aliases">{profile.aliases.map(a=><li key={a.id}><b dir="auto">{a.alias}</b><span>{a.alias_type} · {a.source}</span></li>)}</ul>:<p className="fc-muted">{L("No aliases recorded.","نام جایگزینی ثبت نشده است.")}</p>}</Section>}
    {tab==="intelligence"&&<><div className="fc-inline-actions"><button className="btn-search" onClick={()=>goLocal(`/assistant/${id}`)}>{L("Ask AI about this horse","از هوش مصنوعی درباره این اسب بپرسید")}</button></div>{insights?<HorseIntelligencePanel insights={insights} view={view}/>:metrics?<Section title={L("Pedigree intelligence","تحلیل تبارنامه")} tone="purple"><div className="fc-metric-grid"><Metric label={L("Pedigree completeness","کامل‌بودن تبارنامه")} value={pct(metrics.completenessPercent,view.locale,1)} tone="green"/><Metric label={L("Unique recorded ancestors","نیاکان یکتای ثبت‌شده")} value={num(metrics.uniqueAncestors,view.locale)} tone="blue"/><Metric label={L("Repeated positions","جایگاه‌های تکراری")} value={num(metrics.repeatedAncestorPositions,view.locale)} tone="orange"/></div><p className="fc-muted">{L("The provider exposes pedigree metrics but not the complete horse-insights bundle.","این ارائه‌دهنده شاخص‌های تبارنامه را ارائه می‌کند اما بسته کامل تحلیل اسب در دسترس نیست.")}</p></Section>:<StatePanel status="ready" empty={L("Horse intelligence is unavailable on this provider.","تحلیل اسب در این ارائه‌دهنده در دسترس نیست.")} locale={view.locale}/>}</>}
    {tab==="records"&&<FeiHorseRecordModules view={view} horseId={id}/>}
    </div>
  </main>;
}

function RelationshipSnapshot({horse,view}:{horse:HorseRecord;view:ClassicRuntime}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa);
  const rows=[
    [L("Owner snapshot","مالک در رکورد"),horse.owner_name,horse.owner_name_native],
    [L("Breeder snapshot","پرورش‌دهنده در رکورد"),horse.breeder_name,horse.breeder_name_native],
    [L("Importer snapshot","واردکننده در رکورد"),horse.importer_name,horse.importer_name_native],
    [L("Passport receiver snapshot","گیرنده گذرنامه در رکورد"),horse.passport_receiver_name,horse.passport_receiver_name_native],
  ] as const;
  if(!rows.some(([,latin,native])=>latin||native))return null;
  return <><h3 className="fc-subhead">{L("Record-level relationship labels","برچسب‌های رابطه در خود رکورد")}</h3><div className="fc-association-snapshot">{rows.map(([label,latin,native])=><div key={label}><small>{label}</small><strong dir="auto">{view.locale==="fa"?(native||latin||"—"):(latin||native||"—")}</strong>{latin&&native&&<span dir="auto">{view.locale==="fa"?latin:native}</span>}</div>)}</div></>;
}

export function PeoplePage({view}:{view:ClassicRuntime}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa); const [draft,setDraft]=useState(""); const [q,setQ]=useState(""); const [offset,setOffset]=useState(0); const results=useAsync(signal=>view.platform.people.list({q:q||undefined,limit:40,offset},{signal}),[view.platform,q,offset]);
  const search=(e?:FormEvent)=>{e?.preventDefault();setQ(draft.trim());setOffset(0)}; const reset=()=>{setDraft("");setQ("");setOffset(0)};
  return <main className="fc-main fei-fade-in"><PageTitle title={L("Person Search","جست‌وجوی افراد")} subtitle={L("Canonical owners, breeders, importers and passport receivers from Horse DB registry links.","مالکان، پرورش‌دهندگان، واردکنندگان و گیرندگان گذرنامه مرجع از ارتباطات سامانه ثبت Horse DB.")}/><form onSubmit={search} className="fei-search-form-stack"><DonorPanel className="fei-search-panel fei-person-search-panel"><DonorField label={L("Name","نام")} info={L("Search canonical person names","جست‌وجوی نام‌های مرجع افراد")}><input className="fei-input fei-person-name" value={draft} onChange={e=>setDraft(e.target.value)} dir="auto"/></DonorField><p>{L("Horse DB people are registry persons linked as owners, breeders, importers or passport receivers. Federation Classic does not create a separate athlete entity.","افراد Horse DB اشخاص سامانه ثبت هستند که به‌عنوان مالک، پرورش‌دهنده، واردکننده یا گیرنده گذرنامه مرتبط‌اند. Federation Classic نوع موجودیت جداگانه‌ای به نام ورزشکار ایجاد نمی‌کند.")}</p></DonorPanel><DonorSearchButtons onReset={reset} onSearch={()=>search()} loading={results.status==="loading"} searchLabel={L("Search","جست‌وجو")} resetLabel={L("Reset","پاک کردن")}/></form><DonorPanel className="fei-results-panel"><div className="fei-results-head"><span>{L("People","افراد")}</span><strong>{results.data?num(results.data.people.length,view.locale):"—"}</strong></div>{results.status==="loading"&&!results.data?<StatePanel status="loading" locale={view.locale}/>:results.status==="error"?<StatePanel status="error" error={results.error} locale={view.locale}/>:results.data?.people.length?<><div className="fc-table-wrap"><table className="fc-table"><thead><tr><th>ID</th><th>{L("Name","نام")}</th><th>{L("Owner","مالک")}</th><th>{L("Breeder","پرورش‌دهنده")}</th><th>{L("Importer","واردکننده")}</th><th>{L("Passport receiver","گیرنده گذرنامه")}</th><th>{L("Linked horses","اسب‌های مرتبط")}</th></tr></thead><tbody>{results.data.people.map(p=><tr key={p.id} className="fc-click-row" onClick={()=>view.navigate(horseDbRoutes.person(p.id))}><td><bdi>{p.id}</bdi></td><td><strong dir="auto">{view.locale==="fa"?p.name_native||p.name_latin:p.name_latin||p.name_native}</strong></td><td>{num(p.owner_count,view.locale)}</td><td>{num(p.breeder_count,view.locale)}</td><td>{num(p.importer_count,view.locale)}</td><td>{num(p.passport_receiver_count,view.locale)}</td><td>{num(p.horse_count,view.locale)}</td></tr>)}</tbody></table></div><div className="fc-pagination"><button disabled={offset===0} onClick={()=>setOffset(Math.max(0,offset-40))}>{L("Previous","قبلی")}</button><span>{L("Offset","شروع")} {num(offset,view.locale)}</span><button disabled={results.data.people.length<40} onClick={()=>setOffset(offset+40)}>{L("Next","بعدی")}</button></div></>:<StatePanel status="ready" empty={L("No people match this search.","هیچ فردی با این جست‌وجو یافت نشد.")} locale={view.locale}/>}</DonorPanel></main>;
}
export function PersonPage({view,id}:{view:ClassicRuntime;id:number}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa); const [tab,setTab]=useState("all"); const result=useAsync(signal=>view.platform.people.get(id,{signal}),[view.platform,id]); if(result.status==="loading")return <main className="fc-main"><StatePanel status="loading" locale={view.locale}/></main>; if(result.status==="error"||!result.data)return <main className="fc-main"><StatePanel status="error" error={result.error} locale={view.locale}/></main>; const p=result.data.person;
  const tabs=[{key:"all",label:L("All links","همه ارتباطات")},{key:"owner",label:L("Owner","مالک")},{key:"breeder",label:L("Breeder","پرورش‌دهنده")},{key:"importer",label:L("Importer","واردکننده")},{key:"passport_receiver",label:L("Passport receiver","گیرنده گذرنامه")}];
  const horses=tab==="all"?result.data.horses:result.data.horses.filter(h=>h.role===tab);
  const display=(view.locale==="fa"?p.name_native||p.name_latin:p.name_latin||p.name_native)||`#${p.id}`;
  return <main className="fc-main fei-fade-in fei-person-profile"><PageTitle title={L("Person Profile","پروفایل فرد")} subtitle={L("Canonical Horse DB registry person — not an athlete or sporting profile.","فرد مرجع سامانه ثبت Horse DB — نه پروفایل ورزشکار یا ورزشی.")}/><div className="fei-detail-rows"><div><b>{L("Name","نام")}</b><span dir="auto">{display}</span></div><div><b>{L("Registry person ID","شناسه فرد سامانه ثبت")}</b><span><bdi>{p.id}</bdi></span></div><div><b>{L("Linked horses returned","اسب‌های مرتبط بازگشتی")}</b><span>{num(result.data.horses.length,view.locale)}</span></div></div><div className="fei-person-profile-grid"><DonorFieldset legend={L("Registry role counts","تعداد نقش‌های سامانه ثبت")}><table className="fei-simple-table"><tbody><tr><td>{L("Owner","مالک")}</td><td>{num(p.owner_count,view.locale)}</td></tr><tr><td>{L("Breeder","پرورش‌دهنده")}</td><td>{num(p.breeder_count,view.locale)}</td></tr><tr><td>{L("Importer","واردکننده")}</td><td>{num(p.importer_count,view.locale)}</td></tr><tr><td>{L("Passport receiver","گیرنده گذرنامه")}</td><td>{num(p.passport_receiver_count,view.locale)}</td></tr></tbody></table></DonorFieldset><DonorFieldset legend={L("Associated horses","اسب‌های مرتبط")}><table className="fei-simple-table"><tbody>{result.data.horses.slice(0,8).map(h=><tr key={`${h.id}-${h.role}`}><td><button className="fei-link" onClick={()=>view.navigate(horseDbRoutes.horse(h.id))} dir="auto">{horseName(h,view.locale)}</button></td><td><bdi>{h.id}</bdi></td></tr>)}</tbody></table>{result.data.horses.length>8&&<small>{L("Use the link tabs below to review the complete returned association list.","برای مرور فهرست کامل ارتباطات بازگشتی از زبانه‌های پایین استفاده کنید.")}</small>}</DonorFieldset></div><DonorTabs locale={view.locale} tabs={tabs} active={tab} onChange={setTab}/><DonorPanel className="fei-person-links-panel"><div className="fei-results-head"><span>{tab==="all"?L("All associated horses","همه اسب‌های مرتبط"):roleLabel(tab,view.locale)}</span><strong>{num(horses.length,view.locale)}</strong></div>{horses.length?<div className="fc-table-wrap"><table className="fc-table"><thead><tr><th>ID</th><th>{L("Horse","اسب")}</th><th>{L("Role","نقش")}</th><th>{L("Birth year","سال تولد")}</th><th>{L("Breed","نژاد")}</th><th>{L("Registry no.","شماره ثبت")}</th></tr></thead><tbody>{horses.map(h=><tr key={`${h.id}-${h.role}`} className="fc-click-row" onClick={()=>view.navigate(horseDbRoutes.horse(h.id))}><td><bdi>{h.id}</bdi></td><td><strong dir="auto">{horseName(h,view.locale)}</strong></td><td><Badge tone="purple">{roleLabel(h.role||"linked",view.locale)}</Badge></td><td>{year(h.birth_year,view.locale)}</td><td dir="auto">{h.breed_desc||"—"}</td><td><bdi>{h.register_no||"—"}</bdi></td></tr>)}</tbody></table></div>:<StatePanel status="ready" empty={L("No returned horse links in this role.","هیچ ارتباط بازگشتی اسب در این نقش وجود ندارد.")} locale={view.locale}/>} {result.data.truncated&&<div className="fc-alert">{L("This association list is truncated by the platform limit.","این فهرست ارتباطات بر اساس محدودیت پلتفرم کوتاه شده است.")}</div>}</DonorPanel></main>;
}
function FeiPedigreeTree({layout,view}:{layout:NonNullable<ReturnType<typeof buildPedigreeTreeLayout>>;view:ClassicRuntime}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa); const rtl=view.locale==="fa";
  const byGen=new Map<number,{minX:number;maxX:number}>(); const nodeOf=new Map(layout.nodes.map(n=>[n.key,n] as const));
  for(const n of layout.nodes){const g=n.node.generation;const cur=byGen.get(g);byGen.set(g,{minX:Math.min(cur?.minX??Infinity,n.x),maxX:Math.max(cur?.maxX??-Infinity,n.x+n.width)})}
  const relLabel=(r:string)=>r==="father"?L("Sire","پدر"):r==="mother"?L("Dam","مادر"):r==="root"?L("Subject","موضوع"):L("Kin","خویشاوند");
  const H=layout.height+26;
  return <div className="fei-ped-wrap">
    <div className="fei-ped-legend" aria-hidden="true">
      <span className="fei-leg fei-leg-subject">{L("Subject","موضوع")}</span>
      <span className="fei-leg fei-leg-sire">{L("Sire line","خط پدری")}</span>
      <span className="fei-leg fei-leg-dam">{L("Dam line","خط مادری")}</span>
      <span className="fei-leg fei-leg-repeat">{L("Repeated ancestor","نیای تکراری")}</span>
    </div>
    <div className="fc-tree-scroll">
      <svg className="fc-tree fei-ped-tree" width={layout.width} height={H} viewBox={`0 0 ${layout.width} ${H}`} role="img" aria-label={L("Ancestor pedigree tree","درخت تبارنامه نیاکان")}>
        <g transform="translate(0 24)">
          {[...byGen.entries()].map(([g,r])=><g key={g} className={`fei-ped-band ${g%2?"odd":""}`}>
            <rect x={r.minX-14} y={-18} width={r.maxX-r.minX+28} height={layout.height+14} rx="6"/>
            <text x={(r.minX+r.maxX)/2} y={-24} textAnchor="middle" className="fei-ped-band-label">{g===0?L("Subject","موضوع"):`${L("Generation","نسل")} ${g}`}</text>
          </g>)}
          <g className="fc-tree-edges">{layout.edges.map(edge=>{
            const a=nodeOf.get(edge.from)!; const b=nodeOf.get(edge.to)!;
            const leftToRight=b.x>a.x;
            const x1=leftToRight?a.x+a.width:a.x, x2=leftToRight?b.x:b.x+b.width;
            const y1=a.y+a.height/2, y2=b.y+b.height/2, mx=(x1+x2)/2;
            const cls=[edge.relation==="father"?"sire":edge.relation==="mother"?"dam":"",edge.repeated?"is-repeated":"",edge.cycle?"is-cycle":""].filter(Boolean).join(" ");
            return <path key={edge.key} className={cls} d={`M ${x1} ${y1} C ${mx} ${y1}, ${mx} ${y2}, ${x2} ${y2}`}/>;})}
          </g>
          {layout.nodes.map(n=>{
            const name=horseName(n.node.horse,view.locale); const rel=n.node.relation;
            return <g key={n.key} className={`fc-tree-node fei-ped-node ${rel}${n.node.repeated?" repeated":""}${n.node.cycle?" cycle":""}`} transform={`translate(${n.x} ${n.y})`} onClick={()=>view.navigate(horseDbRoutes.horse(n.node.horse.id))} role="link" tabIndex={-1}>
              <title>{`${name} · #${n.node.horse.id}`}</title>
              <rect width={n.width} height={n.height} rx="6"/>
              <text x={12} y={24} className="name" textAnchor={rtl?"end":undefined}>{rtl?name.slice(0,23):name.slice(0,23)}</text>
              <text x={12} y={43} textAnchor={rtl?"end":undefined}>#{n.node.horse.id} · {n.node.horse.birth_year??"—"}</text>
              <text x={12} y={61} className="rel" textAnchor={rtl?"end":undefined}>{relLabel(rel)}{n.node.repeated?` · ${L("repeat","تکرار")}`:""}{n.node.cycle?` · ${L("cycle","چرخه")}`:""}</text>
            </g>;})}
        </g>
      </svg>
    </div>
  </div>;
}

export function PedigreePage({view,initialId}:{view:ClassicRuntime;initialId?:number}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa); const [idText,setIdText]=useState(initialId?String(initialId):""); const [id,setId]=useState(initialId||0); const [depth,setDepth]=useState(3); const [ancestorTarget,setAncestorTarget]=useState("");
  const pedigree=useAsync(async signal=>{const ancestors=await view.platform.pedigree.ancestors(id,{depth},{signal}); const [descendants,metrics,descendantMetrics,coefficient]=await Promise.all([view.capabilities.descendants?view.platform.pedigree.descendants(id,{depth:Math.min(depth,4),maxNodes:180},{signal}).catch(()=>null):Promise.resolve(null),view.capabilities.metrics?view.platform.pedigree.metrics(id,{depth:Math.min(depth,8)},{signal}).catch(()=>null):Promise.resolve(null),view.capabilities.metrics?view.platform.pedigree.descendantMetrics(id,{depth:Math.min(depth,6)},{signal}).catch(()=>null):Promise.resolve(null),view.capabilities.coefficients?view.platform.pedigree.coefficients(id,{depth:Math.min(depth,8)},{signal}).catch(()=>null):Promise.resolve(null)]);return{ancestors,descendants,metrics,descendantMetrics,coefficient}},[view.platform,id,depth,view.capabilities.descendants,view.capabilities.metrics,view.capabilities.coefficients],id>0);
  const layout=useMemo(()=>pedigree.data?buildPedigreeTreeLayout(pedigree.data.ancestors.tree,{nodeWidth:170,nodeHeight:72,columnGap:64,rowGap:18,maxGeneration:depth,rtl:view.locale==="fa"}):null,[pedigree.data,depth,view.locale]);
  const [pathResult,setPathResult]=useState<string[]>([]); const findPath=async()=>{const aid=Number(ancestorTarget);if(!id||!aid)return;try{const r=await view.platform.pedigree.pathsToAncestor(id,aid,{depth,maxPaths:12});setPathResult(r.paths.map(x=>`${x.branch??"root"}: ${x.path.join(" → ")}`));}catch(e){setPathResult([(e as Error).message])}};
  return <main className="fc-main"><PageTitle title={L("Pedigree & Relationship Tools","ابزار تبارنامه و خویشاوندی")} subtitle={L("Graphical canonical ancestry plus finite-depth pedigree analytics.","تبارنامه نموداریکی مرجع همراه با تحلیل تبار در عمق محدود.")}/><Section title={L("Pedigree subject","موضوع تبارنامه")}><form className="fc-searchline" onSubmit={e=>{e.preventDefault();const n=Number(idText);if(n>0)setId(n)}}><input value={idText} onChange={e=>setIdText(e.target.value.replace(/[^0-9]/g,""))} inputMode="numeric" placeholder={L("Horse registry ID","شناسه سامانه ثبت اسب")}/><select value={depth} onChange={e=>setDepth(Number(e.target.value))}>{[3,4,5,6].map(x=><option key={x} value={x}>{L("Depth","عمق")} {x}</option>)}</select><button className="fc-btn fc-btn-orange"><Icon name="tree"/>{L("Load pedigree","بارگذاری تبارنامه")}</button></form></Section>{!id?<StatePanel status="idle" empty={L("Enter a horse ID to inspect its pedigree.","برای مشاهده تبارنامه، شناسه اسب را وارد کنید.")} locale={view.locale}/>:pedigree.status==="loading"&&!pedigree.data?<StatePanel status="loading" locale={view.locale}/>:pedigree.status==="error"||!pedigree.data?<StatePanel status="error" error={pedigree.error} locale={view.locale}/>:<>
    <div className="fc-metric-grid">{pedigree.data.metrics&&<><Metric label={L("Completeness","کامل‌بودن")} value={pct(pedigree.data.metrics.completenessPercent,view.locale,1)} tone="green"/><Metric label={L("Unique ancestors","نیاکان یکتا")} value={num(pedigree.data.metrics.uniqueAncestors,view.locale)} tone="blue"/><Metric label={L("Repeated positions","جایگاه تکراری")} value={num(pedigree.data.metrics.repeatedAncestorPositions,view.locale)} tone="orange"/></>}{pedigree.data.coefficient&&<Metric label={L("Inbreeding %","درصد هم‌خونی")} value={pct(pedigree.data.coefficient.inbreedingPercent,view.locale,2)} note={L("Finite pedigree depth","عمق محدود تبارنامه")}/>}</div>
    {pedigree.data.descendantMetrics&&<Section title={L("Descendant reach metrics","شاخص‌های گستره نوادگان")}><div className="fc-metric-grid"><Metric label={L("Direct children","فرزندان مستقیم")} value={num(pedigree.data.descendantMetrics.directChildren,view.locale)} tone="blue"/><Metric label={L("Known descendants","نوادگان شناخته")} value={num(pedigree.data.descendantMetrics.knownDescendants,view.locale)} tone="purple"/><Metric label={L("Maximum known generation","بیشترین نسل شناخته")} value={num(pedigree.data.descendantMetrics.maxKnownGeneration,view.locale)} tone="green"/><Metric label={L("Analysis depth","عمق تحلیل")} value={num(pedigree.data.descendantMetrics.depth,view.locale)} tone="gray"/></div><div className="fc-descendant-bars">{pedigree.data.descendantMetrics.generations.map(g=><div key={g.generation}><span>{L("Generation","نسل")} {num(g.generation,view.locale)}</span><b>{num(g.count,view.locale)}</b></div>)}</div>{pedigree.data.descendantMetrics.truncated&&<div className="fc-alert">{L("Descendant traversal reached the platform safety bound.","پیمایش نوادگان به محدودیت ایمنی پلتفرم رسید.")}</div>}<p className="fc-provenance" dir="auto">{localizedAnalysisText(pedigree.data.descendantMetrics.provenance.interpretation,view.locale)} · <bdi>{pedigree.data.descendantMetrics.provenance.algorithmVersion}</bdi></p></Section>}
    {pedigree.data.descendants&&<Section title={L("Recorded descendant tree","درخت نوادگان ثبت‌شده")} tone="plain"><div className="fc-status-strip"><span><b>{L("Depth","عمق")}</b> {num(pedigree.data.descendants.depth,view.locale)}</span><span><b>{L("Returned descendants","نوادگان بازگشتی")}</b> {num(flattenDescendants(pedigree.data.descendants.tree).length,view.locale)}</span><span><b>{L("Truncated","کوتاه‌شده")}</b> {pedigree.data.descendants.truncated?L("Yes","بله"):L("No","خیر")}</span></div><div className="fc-table-wrap"><table className="fc-table fc-table-compact"><thead><tr><th>{L("Generation","نسل")}</th><th>{L("Horse","اسب")}</th><th>{L("Year","سال")}</th><th>{L("State","وضعیت")}</th></tr></thead><tbody>{flattenDescendants(pedigree.data.descendants.tree).map((node,index)=><tr key={`${node.horse.id}-${node.generation}-${index}`} className="fc-click-row" onClick={()=>view.navigate(horseDbRoutes.horse(node.horse.id))}><td>{num(node.generation,view.locale)}</td><td><strong dir="auto">{horseName(node.horse,view.locale)}</strong><small className="fc-secondary">#{node.horse.id}</small></td><td>{year(node.horse.birth_year,view.locale)}</td><td>{node.cycle?L("cycle","چرخه"):node.repeated?L("repeated","تکراری"):L("recorded","ثبت‌شده")}</td></tr>)}</tbody></table></div></Section>}
    <Section title={L("Graphical ancestry","تبارنامه نموداریکی")} tone="plain">{layout&&<FeiPedigreeTree layout={layout} view={view}/>}</Section>
    <div className="fc-two-col"><Section title={L("Generation coverage","پوشش نسل‌ها")}><table className="fc-table fc-table-compact"><thead><tr><th>{L("Gen.","نسل")}</th><th>{L("Known","شناخته")}</th><th>{L("Expected","مورد انتظار")}</th><th>{L("Completeness","کامل‌بودن")}</th></tr></thead><tbody>{pedigree.data.metrics?.generations.map(g=><tr key={g.generation}><td>{num(g.generation,view.locale)}</td><td>{num(g.knownPositions,view.locale)}</td><td>{num(g.expectedPositions,view.locale)}</td><td>{pct(g.completenessPercent,view.locale,1)}</td></tr>)}</tbody></table></Section>{view.capabilities.paths?<Section title={L("Path to recorded ancestor","مسیر تا نیای ثبت‌شده")}><div className="fc-searchline"><input value={ancestorTarget} onChange={e=>setAncestorTarget(e.target.value.replace(/[^0-9]/g,""))} inputMode="numeric" placeholder={L("Ancestor ID","شناسه نیا")}/><button className="fc-btn fc-btn-purple" onClick={findPath}>{L("Trace paths","ردیابی مسیرها")}</button></div>{pathResult.length?<ul className="fc-code-list">{pathResult.map((x,i)=><li key={i}><bdi>{x}</bdi></li>)}</ul>:<p className="fc-muted">{L("Uses the canonical bounded ancestor-path service.","از سرویس مرجع مسیر محدود نیاکان استفاده می‌کند.")}</p>}</Section>:<Section title={L("Ancestor paths","مسیر نیاکان")}><StatePanel status="ready" empty={L("Ancestor-path analysis is unavailable on this provider.","تحلیل مسیر نیاکان در این ارائه‌دهنده در دسترس نیست.")} locale={view.locale}/></Section>}</div>
    {view.capabilities.relationships?<RelationshipTool view={view} defaultFrom={id}/>:<Section title={L("Relationship analysis","تحلیل خویشاوندی")} tone="purple"><StatePanel status="ready" empty={L("Relationship analysis is unavailable on this provider.","تحلیل خویشاوندی در این ارائه‌دهنده در دسترس نیست.")} locale={view.locale}/></Section>}
  </>}</main>;
}

function flattenDescendants(root:PedigreeNode){const rows:PedigreeNode[]=[];const visit=(node:PedigreeNode)=>{for(const child of node.children??[]){rows.push(child);visit(child)}};visit(root);return rows;}

function RelationshipTool({view,defaultFrom}:{view:ClassicRuntime;defaultFrom:number}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa); const [from,setFrom]=useState(String(defaultFrom)); const [to,setTo]=useState(""); const [result,setResult]=useState<{rel:RelationshipResponse;coef:RelationshipCoefficientResponse|null}|null>(null); const [error,setError]=useState(""); const [busy,setBusy]=useState(false);
  const run=async()=>{const a=Number(from),b=Number(to);if(!a||!b)return;setBusy(true);setError("");try{const rel=await view.platform.relationships.commonAncestors(a,b,{depth:6});const coef=view.capabilities.coefficients?await view.platform.relationships.coefficients(a,b,{depth:6}).catch(()=>null):null;setResult({rel,coef})}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
  const summary=result?.rel.summary,atlas=result?.rel.atlas,coef=result?.coef;
  return <Section title={L("Relationship / common-ancestor analysis","تحلیل خویشاوندی / نیای مشترک")} tone="purple"><div className="fc-searchline"><input value={from} onChange={e=>setFrom(e.target.value.replace(/[^0-9]/g,""))} inputMode="numeric" placeholder={L("Horse A ID","شناسه اسب A")}/><input value={to} onChange={e=>setTo(e.target.value.replace(/[^0-9]/g,""))} inputMode="numeric" placeholder={L("Horse B ID","شناسه اسب B")}/><button className="fc-btn fc-btn-orange" onClick={run} disabled={busy}>{busy?L("Comparing…","در حال مقایسه…"):L("Compare","مقایسه")}</button></div>{error&&<div className="fc-alert fc-alert-danger" dir="auto">{error}</div>}{result&&<>
    <div className="fc-metric-grid"><Metric label={L("Relationship kind","نوع خویشاوندی")} value={summary?.kind?.replaceAll("_"," ")||L("Related","مرتبط")}/><Metric label={L("Common ancestors","نیاکان مشترک")} value={num(summary?.commonAncestorCount??result.rel.commonAncestors.length,view.locale)} tone="blue"/>{summary?.closestTotalDepth!=null&&<Metric label={L("Closest combined depth","کمترین عمق مجموع")} value={num(summary.closestTotalDepth,view.locale)} tone="gray"/>}{summary?.directGeneration!=null&&<Metric label={L("Direct generation","نسل مستقیم")} value={num(summary.directGeneration,view.locale)} tone="green"/>}{coef&&<Metric label={L("Relationship %","درصد خویشاوندی")} value={pct(coef.relationshipPercent,view.locale,2)} tone="orange"/>}{coef&&<Metric label={L("Kinship %","درصد قرابت")} value={pct(coef.kinshipPercent,view.locale,2)} tone="green"/>}</div>
    {summary&&<div className="fc-status-strip"><span><b>{L("A depth","عمق A")}</b> {num(summary.fromDepth,view.locale)}</span><span><b>{L("B depth","عمق B")}</b> {num(summary.toDepth,view.locale)}</span><span><b>{L("Paternal connections","اتصالات پدری")}</b> {num(summary.paternalConnectionCount,view.locale)}</span><span><b>{L("Maternal connections","اتصالات مادری")}</b> {num(summary.maternalConnectionCount,view.locale)}</span><span><b>{L("Cross-branch connections","اتصالات بین شاخه‌ای")}</b> {num(summary.crossBranchConnectionCount,view.locale)}</span><span><b>{L("Integrity","یکپارچگی")}</b> {summary.integrity.cycleDetected?L("cycle detected","چرخه شناسایی شد"):summary.integrity.truncated?L("truncated","کوتاه‌شده"):L("ok","سالم")}</span></div>}
    <div className="fc-card-table">{result.rel.commonAncestors.slice(0,30).map(a=><button key={a.horse.id} onClick={()=>view.navigate(horseDbRoutes.horse(a.horse.id))}><span><strong dir="auto">{horseName(a.horse as HorseRecord,view.locale)}</strong><small>#{a.horse.id} · {L("depths","عمق‌ها")} {a.fromDepth}/{a.toDepth} · {L("total","مجموع")} {a.totalDepth}</small><small><bdi>{a.fromPath.join(" → ")}</bdi> ↔ <bdi>{a.toPath.join(" → ")}</bdi></small></span><Icon name="arrow"/></button>)}</div>
    {atlas&&<details className="fc-details"><summary>{L("Bounded relationship path atlas","اطلس محدود مسیر خویشاوندی")} · {num(atlas.tracedConnectionCount,view.locale)} {L("connections","اتصال")}</summary><div className="fc-table-wrap"><table className="fc-table fc-table-compact"><thead><tr><th>{L("Via ancestor","از طریق نیا")}</th><th>{L("A branch / depth","شاخه / عمق A")}</th><th>{L("B branch / depth","شاخه / عمق B")}</th><th>{L("Combined depth","عمق مجموع")}</th><th>{L("Paths","مسیرها")}</th></tr></thead><tbody>{atlas.connections.map((c,i)=><tr key={`${c.via.id}-${i}`}><td><button className="fc-link" onClick={()=>view.navigate(horseDbRoutes.horse(c.via.id))} dir="auto">{horseName(c.via as HorseRecord,view.locale)}</button></td><td>{c.fromBranch||"—"} / {num(c.fromDepth,view.locale)}</td><td>{c.toBranch||"—"} / {num(c.toDepth,view.locale)}</td><td>{num(c.totalDepth,view.locale)}</td><td><bdi>{c.fromPath.join("→")}</bdi> ↔ <bdi>{c.toPath.join("→")}</bdi></td></tr>)}</tbody></table></div>{atlas.pathEnumerationTruncated&&<div className="fc-alert">{L("Path enumeration reached its platform bound.","شمارش مسیرها به محدودیت پلتفرم رسید.")}</div>}<p className="fc-provenance" dir="auto">{localizedAnalysisText(atlas.provenance.interpretation,view.locale)} · <bdi>{atlas.provenance.algorithmVersion}</bdi></p></details>}
    {coef&&<Section title={L("Finite-depth relationship coefficients","ضرایب خویشاوندی در عمق محدود")}><div className="fc-metric-grid"><Metric label={L("Relationship coefficient","ضریب خویشاوندی")} value={coef.relationshipCoefficient==null?"—":String(coef.relationshipCoefficient)}/><Metric label={L("Kinship coefficient","ضریب قرابت")} value={coef.kinshipCoefficient==null?"—":String(coef.kinshipCoefficient)} tone="green"/><Metric label={L("Horse A COI","هم‌خونی اسب A")} value={pct(coef.fromInbreedingPercent,view.locale,2)} tone="blue"/><Metric label={L("Horse B COI","هم‌خونی اسب B")} value={pct(coef.toInbreedingPercent,view.locale,2)} tone="orange"/><Metric label={L("Horse A completeness","کامل‌بودن اسب A")} value={pct(coef.fromPedigreeCompletenessPercent,view.locale,1)}/><Metric label={L("Horse B completeness","کامل‌بودن اسب B")} value={pct(coef.toPedigreeCompletenessPercent,view.locale,1)}/><Metric label={L("Analyzed horses","اسب‌های تحلیل‌شده")} value={num(coef.analyzedHorses,view.locale)} tone="gray"/><Metric label={L("Assumed founders","بنیان‌گذاران فرض‌شده")} value={num(coef.assumedFounderNodes,view.locale)} tone="gray"/><Metric label={L("Boundary parent refs","ارجاعات والد مرزی")} value={num(coef.boundaryParentReferences,view.locale)} tone="gray"/></div><div className="fc-status-strip"><span><b>{L("Status","وضعیت")}</b> {code(coef.status,view.locale)}</span><span><b>{L("Cycle","چرخه")}</b> {coef.integrity.cycleDetected?L("yes","بله"):L("no","خیر")}</span><span><b>{L("Truncated","کوتاه‌شده")}</b> {coef.integrity.truncated?L("yes","بله"):L("no","خیر")}</span></div><p className="fc-provenance" dir="auto">{localizedAnalysisText(coef.provenance.interpretation,view.locale)} · {founderAssumptionLabel(coef.provenance.founderAssumption,view.locale)} · <bdi>{coef.provenance.algorithmVersion}</bdi></p></Section>}
  </>}</Section>;
}


export function AiResearchPage({view,horseId}:{view:ClassicRuntime;horseId?:number}){const L=(en:string,fa:string)=>t(view.locale,en,fa);return <main className="fc-main"><PageTitle title={L("AI Research Assistant","دستیار پژوهشی هوش مصنوعی")} subtitle={L("Agentic registry research using canonical Horse-DB search, pedigree, analytics and published content.","پژوهش عامل‌محور سامانه ثبت با استفاده از جست‌وجو، تبارنامه، تحلیل و محتوای مرجع Horse-DB.")}/><AssistantPanel platform={view.platform} locale={view.locale} fullPage pageContext={{route:view.route,...(horseId?{horseId}:{})}}/></main>}
export function IntelligencePage({view,section="rankings"}:{view:ClassicRuntime;section?:"rankings"|"timeline"|"places"}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa);
  const [rankCategory,setRankCategory]=useState<"sires"|"dams"|"ancestors"|"owners"|"breeders"|"importers">("sires");
  const [timelineDraft,setTimelineDraft]=useState("");
  const [timelineDecade,setTimelineDecade]=useState("");
  const [placeDraft,setPlaceDraft]=useState("");
  const [placeQuery,setPlaceQuery]=useState("");
  const data=useAsync(signal=>view.platform.analytics.registry({signal}),[view.platform],view.capabilities.analytics);
  if(!view.capabilities.analytics)return <main className="fc-main"><PageTitle title={L("Registry Intelligence","تحلیل سامانه ثبت")}/><StatePanel status="ready" empty={L("Registry analytics is unavailable on this provider.","تحلیل سامانه ثبت در این ارائه‌دهنده در دسترس نیست.")} locale={view.locale}/></main>;
  if(data.status==="loading")return <main className="fc-main"><StatePanel status="loading" locale={view.locale}/></main>;
  if(data.status==="error"||!data.data)return <main className="fc-main"><StatePanel status="error" error={data.error||L("Registry analytics unavailable","تحلیل سامانه ثبت در دسترس نیست")} locale={view.locale}/></main>;
  const a=data.data;

  if(section==="timeline"){
    const years=(a.birthYears??[]).filter(x=>!timelineDecade||Math.floor(x.year/10)*10===Number(timelineDecade));
    const decadeOptions=a.birthDecades.map(x=>x.decade);
    return <main className="fc-main fei-other-page fei-calendar-adaptation"><PageTitle title={L("Registry Timeline","خط زمانی سامانه ثبت")} subtitle={L("Donor calendar composition adapted to canonical birth-year analytics; this is not a sporting calendar.","ترکیب‌بندی تقویم الگو با تحلیل مرجع سال تولد سازگار شده است؛ این تقویم مسابقات نیست.")}/>
      <DonorSectionHeading>{L("Timeline criteria","معیارهای خط زمانی")}</DonorSectionHeading><DonorPanel className="fei-timeline-filter"><div className="fei-form-grid"><DonorField label={L("Birth decade","دهه تولد")}><select value={timelineDraft} onChange={e=>setTimelineDraft(e.target.value)}><option value="">{L("All recorded decades","همه دهه‌های ثبت‌شده")}</option>{decadeOptions.map(d=><option key={d} value={d}>{d}s</option>)}</select></DonorField></div><DonorSearchButtons onReset={()=>{setTimelineDraft("");setTimelineDecade("")}} onSearch={()=>setTimelineDecade(timelineDraft)} resetLabel={L("Reset","بازنشانی")} searchLabel={L("Search","جست‌وجو")}/></DonorPanel>
      <DonorSectionHeading>{L("Registry timeline results","نتایج خط زمانی سامانه ثبت")}</DonorSectionHeading><DonorPanel className="fei-timeline-results"><div className="fc-table-wrap"><table className="fc-table"><thead><tr><th>{L("Birth year","سال تولد")}</th><th>{L("Recorded horses","اسب‌های ثبت‌شده")}</th></tr></thead><tbody>{years.length?years.map(x=><tr key={x.year}><td>{year(x.year,view.locale)}</td><td>{num(x.count,view.locale)}</td></tr>):<tr><td colSpan={2}>{L("No canonical birth-year rows match this filter.","هیچ ردیف مرجع سال تولد با این فیلتر مطابقت ندارد.")}</td></tr>}</tbody></table></div></DonorPanel>
      <Section title={L("Birth decades","دهه‌های تولد")}><BarList rows={a.birthDecades.map(x=>({label:`${x.decade}s`,count:x.count}))} locale={view.locale}/></Section>
      {a.birthYears&&a.birthYears.length>0&&<Section title={L("Recorded birth-year distribution","توزیع سال تولد ثبت‌شده")} tone="plain"><div className="fc-timeline-grid">{a.birthYears.slice(-60).map(x=><div key={x.year}><b>{year(x.year,view.locale)}</b><span style={{height:`${Math.max(4,Math.min(90,(x.count/Math.max(...a.birthYears!.map(y=>y.count)))*90))}px`}}/><small>{num(x.count,view.locale)}</small></div>)}</div></Section>}
      <Section title={L("Analytics provenance","منشأ تحلیل")}><dl className="fc-definition"><div><dt>{L("Generated","تولید شده")}</dt><dd><bdi>{a.generatedAt}</bdi></dd></div><div><dt>{L("Algorithm","الگوریتم")}</dt><dd><bdi>{a.algorithmVersion}</bdi></dd></div><div><dt>{L("Source revision","بازبینی منبع")}</dt><dd><bdi>{a.sourceRevision}</bdi></dd></div></dl></Section>
    </main>;
  }

  if(section==="places"){
    const q=placeQuery.trim().toLocaleLowerCase();
    const places=a.topBirthPlaces.filter(x=>!q||x.label.toLocaleLowerCase().includes(q));
    return <main className="fc-main fei-other-page fei-geography-adaptation"><PageTitle title={L("Places / Registry Geography","مکان‌ها / جغرافیای سامانه ثبت")} subtitle={L("Donor federation-card composition adapted to real birth-place evidence; no national-federation entities are fabricated.","ترکیب‌بندی کارت‌های فدراسیون الگو با شواهد واقعی محل تولد سازگار شده است؛ هیچ نهاد فدراسیون ملی ساختگی نمایش داده نمی‌شود.")}/>
      <DonorSectionHeading>{L("Place criteria","معیارهای مکان")}</DonorSectionHeading><DonorPanel><div className="fei-form-grid"><DonorField label={L("Birth place contains","محل تولد شامل")}><input value={placeDraft} onChange={e=>setPlaceDraft(e.target.value)} placeholder={L("Canonical place text","متن مرجع مکان")} dir="auto"/></DonorField></div><DonorSearchButtons onReset={()=>{setPlaceDraft("");setPlaceQuery("")}} onSearch={()=>setPlaceQuery(placeDraft)} resetLabel={L("Reset","بازنشانی")} searchLabel={L("Search","جست‌وجو")}/></DonorPanel>
      <DonorSectionHeading>{L("Top recorded birth places","محل‌های تولد پرتعداد ثبت‌شده")}</DonorSectionHeading><div className="fei-place-cards">{places.length?places.slice(0,24).map((r,i)=><article key={r.label} className="fei-place-card"><div className="fei-place-card-rank">{num(i+1,view.locale)}</div><div><strong dir="auto">{r.label}</strong><small>{L("Recorded horses","اسب‌های ثبت‌شده")}</small></div><b>{num(r.count,view.locale)}</b></article>):<div className="fc-alert">{L("No canonical birth-place rows match this filter.","هیچ ردیف مرجع محل تولد با این فیلتر مطابقت ندارد.")}</div>}</div>
      <div className="fc-two-col"><Section title={L("Top birth places","محل‌های تولد پرتعداد")}><BarList rows={a.topBirthPlaces} locale={view.locale}/></Section><Section title={L("Top breeds","نژادهای پرتعداد")}><BarList rows={a.topBreeds} locale={view.locale}/></Section></div><Section title={L("Population status","وضعیت جمعیت")}><div className="fc-metric-grid">{a.activity&&Object.entries(a.activity).map(([k,v])=><Metric key={k} label={k} value={num(v.count,view.locale)} note={pct(v.percent,view.locale,1)} tone={k==="imported"?"blue":k==="deceased"?"gray":"purple"}/>)}</div></Section>
    </main>;
  }

  const rankOptions:[typeof rankCategory,string,string,"horses"|"people"|"pedigree",string][]=[
    ["sires",L("Sires","پدران"),L("Recorded offspring","فرزند ثبت‌شده"),"horses","#2f6fa5"],
    ["dams",L("Dams","مادران"),L("Recorded offspring","فرزند ثبت‌شده"),"horses","#a85f4a"],
    ["ancestors",L("Ancestors","نیاکان"),L("Depth-4 representation","نمایندگی در عمق ۴"),"pedigree","#4b8a64"],
    ["owners",L("Owners","مالکان"),L("Registry links","ارتباط سامانه ثبت"),"people","#777777"],
    ["breeders",L("Breeders","پرورش‌دهندگان"),L("Registry links","ارتباط سامانه ثبت"),"people","#d88b16"],
    ["importers",L("Importers","واردکنندگان"),L("Registry links","ارتباط سامانه ثبت"),"people","#7a1c7b"],
  ];
  return <main className="fc-main fei-other-page fei-rankings-adaptation"><PageTitle title={L("Registry Intelligence Rankings","رتبه‌بندی تحلیل سامانه ثبت")} subtitle={L("Donor ranking-selector composition adapted to counts of real registry links — never sporting merit or competition rank.","ترکیب‌بندی انتخاب رتبه الگو با شمار ارتباطات واقعی سامانه ثبت سازگار شده است — نه امتیاز ورزشی یا رتبه مسابقه.")}/><div className="fei-ranking-tiles">{rankOptions.map(([key,label,note,icon,color])=><button key={key} type="button" className={`fei-ranking-tile ${rankCategory===key?"is-active":""}`} aria-pressed={rankCategory===key} onClick={()=>setRankCategory(key)}><RegistryTileIcon color={color} variant={icon}/><span><strong>{label}</strong><small>{note}</small></span></button>)}</div><div className="fei-ranking-result">{rankCategory==="sires"?<RankTable title={L("Top recorded sires by offspring","پدران پرتعداد بر اساس فرزند ثبت‌شده")} rows={a.progeny.topSires} view={view}/>:rankCategory==="dams"?<RankTable title={L("Top recorded dams by offspring","مادران پرتعداد بر اساس فرزند ثبت‌شده")} rows={a.progeny.topDams} view={view}/>:rankCategory==="ancestors"?<RankTable title={L("Top represented ancestors at depth 4","نیاکان پرتکرار در عمق ۴")} rows={a.pedigree.topRepresentedAncestorsDepth4} view={view}/>:rankCategory==="owners"?<PersonRankTable title={L("Top owners by registry links","مالکان پرتعداد بر اساس ارتباط سامانه ثبت")} rows={a.people?.topOwners??[]} view={view}/>:rankCategory==="breeders"?<PersonRankTable title={L("Top breeders by registry links","پرورش‌دهندگان پرتعداد بر اساس ارتباط سامانه ثبت")} rows={a.people?.topBreeders??[]} view={view}/>:<PersonRankTable title={L("Top importers by registry links","واردکنندگان پرتعداد بر اساس ارتباط سامانه ثبت")} rows={a.people?.topImporters??[]} view={view}/>}</div></main>;
}
function BarList({rows,locale}:{rows:Array<{label:string;count:number}>;locale:"en"|"fa"|"ar"}){const max=Math.max(1,...rows.map(x=>x.count));return <div className="fc-bars">{rows.slice(0,20).map(r=><div key={r.label}><span dir="auto">{r.label}</span><i><b style={{width:`${(r.count/max)*100}%`}}/></i><strong>{num(r.count,locale)}</strong></div>)}</div>}
function RankTable({title,rows,view}:{title:string;rows:RegistryAnalyticsResponse["progeny"]["topParents"];view:ClassicRuntime}){return <Section title={title}><table className="fc-table fc-table-compact"><thead><tr><th>#</th><th>{t(view.locale,"Horse","اسب")}</th><th>{t(view.locale,"Recorded count","تعداد ثبت‌شده")}</th></tr></thead><tbody>{rows.slice(0,15).map((r,i)=><tr key={r.id} className="fc-click-row" onClick={()=>view.navigate(horseDbRoutes.horse(r.id))}><td>{num(i+1,view.locale)}</td><td><strong dir="auto">{view.locale==="fa"?r.name_native||r.name_latin:r.name_latin||r.name_native}</strong><small className="fc-secondary">#{r.id}</small></td><td>{num(r.count,view.locale)}</td></tr>)}</tbody></table></Section>}
function PersonRankTable({title,rows,view}:{title:string;rows:Array<{id:number;name_latin?:string|null;name_native?:string|null;count:number}>;view:ClassicRuntime}){return <Section title={title}><table className="fc-table fc-table-compact"><thead><tr><th>#</th><th>{t(view.locale,"Person","فرد")}</th><th>{t(view.locale,"Registry links","ارتباط سامانه ثبت")}</th></tr></thead><tbody>{rows.slice(0,15).map((r,i)=><tr key={r.id} className="fc-click-row" onClick={()=>view.navigate(horseDbRoutes.person(r.id))}><td>{num(i+1,view.locale)}</td><td><strong dir="auto">{view.locale==="fa"?r.name_native||r.name_latin:r.name_latin||r.name_native}</strong></td><td>{num(r.count,view.locale)}</td></tr>)}</tbody></table></Section>}

export function QualityPage({view}:{view:ClassicRuntime}){const L=(en:string,fa:string)=>t(view.locale,en,fa);const data=useAsync(signal=>view.platform.quality.summary({signal}),[view.platform],view.capabilities.quality);if(!view.capabilities.quality)return <main className="fc-main"><PageTitle title={L("Registry Data Quality","کیفیت داده سامانه ثبت")}/><StatePanel status="ready" empty={L("Quality analytics is unavailable on this provider.","تحلیل کیفیت در این ارائه‌دهنده در دسترس نیست.")} locale={view.locale}/></main>;return <main className="fc-main"><PageTitle title={L("Registry Data Quality","کیفیت داده سامانه ثبت")} subtitle={L("Open issue summary from the canonical quality service.","خلاصه مسائل باز از سرویس مرجع کیفیت.")}/>{data.status==="loading"?<StatePanel status="loading" locale={view.locale}/>:data.status==="error"||!data.data?<StatePanel status="error" error={data.error} locale={view.locale}/>:<><div className="fc-metric-grid"><Metric label={L("Open issues","مسائل باز")} value={num(data.data.openIssues,view.locale)} tone="orange"/>{data.data.severities.map(s=><Metric key={s.value} label={s.value} value={num(s.count,view.locale)} tone={s.value==="error"?"orange":s.value==="warning"?"purple":"gray"}/>)}</div><div className="fc-two-col"><Section title={L("Severity distribution","توزیع شدت")}><BarList rows={data.data.severities.map(x=>({label:x.value,count:x.count}))} locale={view.locale}/></Section><Section title={L("Top issue codes","کدهای پرتکرار مسئله")}><BarList rows={data.data.topIssueCodes.map(x=>({label:x.value,count:x.count}))} locale={view.locale}/></Section></div>{data.data.snapshotStale&&<div className="fc-alert">{L("Derived snapshot is stale; platform indicates an exact live fallback is being served.","تصویر مشتق‌شده قدیمی است؛ پلتفرم اعلام می‌کند جایگزین زنده و دقیق ارائه می‌شود.")}</div>}</>}</main>}

export function WorkflowPage({view,goLocal}:{view:ClassicRuntime;goLocal:(p:string)=>void}){return <WorkflowSurface view={view} goLocal={goLocal}/>;}

export function AuthPage({view}:{view:ClassicRuntime}){
  const scope=usePrincipalScope(view.user,view.permissions);
  const [authNotice,setAuthNotice]=useState<"pending"|"unconfirmed"|null>(null);
  const [checking,setChecking]=useState(false);
  const [noticeError,setNoticeError]=useState("");
  const L=(en:string,fa:string)=>t(view.locale,en,fa);
  return <><AccountSecuritySessionNotice platform={view.platform} locale={view.locale}/>{authNotice&&<section className="hdb-account-controls"><p role={authNotice==="pending"?"status":"alert"}>{authNotice==="pending"?L("Signing out… Please wait before signing in again.","در حال خروج… پیش از ورود دوباره منتظر بمانید."):L("Sign-out could not be confirmed. Check account status before continuing.","خروج تأیید نشد. پیش از ادامه وضعیت حساب را بررسی کنید.")}</p>{authNotice==="unconfirmed"&&<button disabled={checking} onClick={()=>{setChecking(true);setNoticeError("");void view.platform.auth.me().then(()=>setAuthNotice(null)).catch(error=>setNoticeError((error as Error).message)).finally(()=>setChecking(false))}}>{L("Check account status","بررسی وضعیت حساب")}</button>}{noticeError&&<p role="alert">{noticeError}</p>}</section>}<AuthPageForPrincipal key={scope} view={view} authNotice={authNotice} setAuthNotice={setAuthNotice}/></>;
}
function AuthPageForPrincipal({view,authNotice,setAuthNotice}:{view:ClassicRuntime;authNotice:"pending"|"unconfirmed"|null;setAuthNotice:(value:"pending"|"unconfirmed"|null)=>void}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa);const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [showPassword,setShowPassword]=useState(false);const [busy,setBusy]=useState(false);const [message,setMessage]=useState("");
  if(!view.capabilities.authentication)return <main className="fc-main fc-auth-page fei-login-page"><div className="fei-login-brand"><FederationClassicFullLogo fa={view.locale==="fa"}/><h1>{L("Login to Horse DB","ورود به Horse DB")}</h1></div><StatePanel status="ready" empty={L("Interactive authentication is unavailable on this provider.","احراز هویت تعاملی در این ارائه‌دهنده در دسترس نیست.")} locale={view.locale}/><button className="fei-login-back fei-link" onClick={()=>view.navigate(horseDbRoutes.home())}>{L("← Back to Horse DB Registry","→ بازگشت به سامانه ثبت Horse DB")}</button></main>;
  const login=async(e:FormEvent)=>{e.preventDefault();if(authNotice==="pending")return;setBusy(true);setMessage("");try{const r=await view.platform.auth.login({email:email.trim(),password});setAuthNotice(null);setMessage(r.user?L("Signed in successfully.","ورود با موفقیت انجام شد."):L("Authentication completed without an active user.","احراز هویت انجام شد اما کاربر فعالی وجود ندارد."));setPassword("");if(r.user)view.navigate(horseDbRoutes.home())}catch(e){setMessage((e as Error).message)}finally{setBusy(false)}};
  const logout=async()=>{setBusy(true);setAuthNotice("pending");try{await view.platform.auth.logout();setAuthNotice(null);setMessage(L("Signed out.","خروج انجام شد."))}catch(e){setAuthNotice("unconfirmed");setMessage((e as Error).message)}finally{setBusy(false)}};
  const demoLogin=async()=>{if(authNotice==="pending")return;setBusy(true);setMessage("");try{const r=await view.platform.auth.demoAdmin();setAuthNotice(null);setMessage(r.user?L("Demo administrator session started.","نشست مدیر نمونه آغاز شد."):L("Demo login completed without an active user.","ورود نمونه بدون کاربر فعال انجام شد."));if(r.user)view.navigate(horseDbRoutes.home())}catch(e){setMessage((e as Error).message)}finally{setBusy(false)}};
  return <main className="fc-main fc-auth-page fei-login-page"><div className="fei-login-brand"><FederationClassicFullLogo fa={view.locale==="fa"}/><h1>{view.user?L("Horse DB Account","حساب Horse DB"):L("Login to Horse DB","ورود به Horse DB")}</h1></div><p>{L("Sign in to manage your registry requests and authorized records.","برای مدیریت درخواست‌های ثبت و پرونده‌های مجاز، وارد حساب خود شوید.")}</p>{view.user?<DonorPanel className="fei-login-box"><div className="fc-auth-user"><Icon name="shield"/><div><b dir="auto">{view.user.display_name}</b><span><bdi>{view.user.email}</bdi></span></div><button className="btn-reset" onClick={logout} disabled={busy}>{L("Sign out","خروج")}</button></div>{message&&<div className="fc-inline-message" dir="auto">{message}</div>}</DonorPanel>:<form className="fei-login-box" onSubmit={login}><p>{L("Please enter your Horse DB email and password.","لطفاً ایمیل و گذرواژه Horse DB خود را وارد کنید.")}</p><p className="fei-login-warning">{L("Passwords are case sensitive.","گذرواژه به حروف بزرگ و کوچک حساس است.")}</p>{message&&<div className="fc-alert fc-alert-danger" role="alert" dir="auto">{message}</div>}<div className="fei-login-fields"><label>{L("Email:","ایمیل:")}<input className="fei-input" type="email" value={email} onChange={e=>setEmail(e.target.value)} required dir="ltr" autoComplete="username" autoFocus/></label><label>{L("Password:","گذرواژه:")}<span className="fei-password-control"><input className="fei-input" type={showPassword?"text":"password"} value={password} onChange={e=>setPassword(e.target.value)} required dir="ltr" autoComplete="current-password"/><button type="button" className="fei-link" onClick={()=>setShowPassword(v=>!v)}>{showPassword?L("Hide","پنهان"):L("Show","نمایش")}</button></span></label><div className="fei-login-submit"><button className="btn-search" disabled={busy||authNotice==="pending"}>{busy||authNotice==="pending"?<span className="fei-spinner"/>:L("Login","ورود")}</button></div>{view.platformMeta?.demoAdminLoginAvailable&&<div className="fei-demo-login"><span>{L("Demo environment","محیط نمونه")}</span><button type="button" className="btn-reset" onClick={()=>void demoLogin()} disabled={busy||authNotice==="pending"}>{L("Enter as demo administrator","ورود به‌عنوان مدیر نمونه")}</button></div>}</div></form>}{view.user&&<AccountSecurityPanel platform={view.platform} locale={view.locale} scope={view.user.id}/>}<button className="fei-login-back fei-link" onClick={()=>view.navigate(horseDbRoutes.home())}>{L("← Back to Horse DB Registry","→ بازگشت به سامانه ثبت Horse DB")}</button></main>;
}
export function BreedingPage({view}:{view:ClassicRuntime}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa); const [sire,setSire]=useState("");const [dam,setDam]=useState("");const [depth,setDepth]=useState(6);
  const scope=usePrincipalScope(view.user,view.permissions);
  const [query,setQuery]=useState<{sire:number;dam:number;depth:number;revision:number}|null>(null);
  const resource=useDomainResource('fei-pedigree-pair',`${scope}:${JSON.stringify(query)}`,signal=>view.platform.breeding.pairingAnalysis(query!.sire,query!.dam,{depth:query!.depth},{signal}),{enabled:view.capabilities.breeding&&query!=null});
  const result=resource.state.phase==='ready'||resource.state.phase==='reloading'?resource.state.data:null;
  const busy=resource.state.phase==='loading'||resource.state.phase==='reloading';
  const valid=Number.isSafeInteger(Number(sire))&&Number(sire)>0&&Number.isSafeInteger(Number(dam))&&Number(dam)>0&&Number(sire)!==Number(dam);
  const failed=['error','forbidden','unavailable'].includes(resource.state.phase);
  if(!view.capabilities.breeding)return <main className="fc-main"><PageTitle title={L("Pedigree Breeding Analysis","تحلیل جفت‌گیری تبارنامه‌ای")}/><StatePanel status="ready" empty={L("Breeding analysis is unavailable on this provider.","تحلیل جفت‌گیری در این ارائه‌دهنده در دسترس نیست.")} locale={view.locale}/></main>;
  const run=()=>{if(!valid||busy)return;setQuery(previous=>({sire:Number(sire),dam:Number(dam),depth,revision:(previous?.revision??0)+1}));};
  const d=result?.diversityProjection;
  return <main className="fc-main"><PageTitle title={L("Breeding evidence","شواهد جفت‌گیری")} subtitle={L("Recorded pedigree calculations and reviewed genetic evidence are shown separately, with their coverage limits.","محاسبات تبار ثبت‌شده و شواهد ژنتیکی بررسی‌شده به‌صورت جداگانه و همراه با محدودیت پوشش نمایش داده می‌شوند.")}/>
    <Section title={L("Pairing inputs","ورودی‌های جفت‌گیری")}><form className="fc-searchline fc-pairing-inputs" onSubmit={event=>{event.preventDefault();run();}}><label>{L("Sire ID","شناسه پدر")}<input value={sire} onChange={e=>{setSire(e.target.value.replace(/[^0-9]/g,""));setQuery(null);}} inputMode="numeric" required/></label><label>{L("Dam ID","شناسه مادر")}<input value={dam} onChange={e=>{setDam(e.target.value.replace(/[^0-9]/g,""));setQuery(null);}} inputMode="numeric" required/></label><label>{L("Generations","تعداد نسل")}<select value={depth} onChange={e=>{setDepth(Number(e.target.value));setQuery(null);}}>{[4,5,6,7,8].map(x=><option key={x} value={x}>{num(x,view.locale)}</option>)}</select></label><button type="submit" className="fc-btn fc-btn-orange" disabled={busy||!valid}>{busy?L("Analyzing…","در حال تحلیل…"):L("Analyze pairing","تحلیل جفت")}</button></form>{busy&&<p role="status">{L("Reading recorded pedigree…","در حال خواندن تبار ثبت‌شده…")}</p>}{failed&&<div className="fc-alert fc-alert-danger" role="alert"><p>{resource.state.phase==='forbidden'?L("This account cannot access this comparison.","این حساب به این مقایسه دسترسی ندارد."):resource.state.phase==='unavailable'?L("Pairing analysis is unavailable in this environment.","تحلیل جفت در این محیط در دسترس نیست."):L("The analysis could not be loaded. Your inputs are preserved.","تحلیل بارگیری نشد. ورودی‌های شما حفظ شده‌اند.")}</p><button type="button" className="btn-reset" onClick={resource.retry}>{L("Try again","تلاش دوباره")}</button></div>}</Section>
    {result&&<><div className="fc-status-strip"><span><b>{L("Status","وضعیت")}</b> {code(result.status,view.locale)}</span><span><b>{L("Depth","عمق")}</b> {num(result.depth,view.locale)}</span><span><b>{L("Integrity","یکپارچگی")}</b> {result.integrity.cycleDetected?L("cycle detected","چرخه شناسایی شد"):result.integrity.truncated?L("truncated","کوتاه‌شده"):L("ok","سالم")}</span></div><div className="fc-metric-grid"><Metric label={L("Projected offspring COI","هم‌خونی پیش‌بینی‌شده فرزند")} value={pct(result.projectedOffspringInbreedingPercent,view.locale,2)} tone="orange"/><Metric label={L("Parental relationship","خویشاوندی والدین")} value={pct(result.parentalRelationshipPercent,view.locale,2)} tone="purple"/><Metric label={L("Parental kinship","قرابت والدین")} value={pct(result.parentalKinshipPercent,view.locale,2)} tone="green"/><Metric label={L("Sire COI","هم‌خونی پدر")} value={pct(result.sireInbreedingPercent,view.locale,2)} tone="blue"/><Metric label={L("Dam COI","هم‌خونی مادر")} value={pct(result.damInbreedingPercent,view.locale,2)} tone="orange"/><Metric label={L("Sire completeness","کامل‌بودن تبار پدر")} value={pct(result.sirePedigreeCompletenessPercent,view.locale,1)} tone="blue"/><Metric label={L("Dam completeness","کامل‌بودن تبار مادر")} value={pct(result.damPedigreeCompletenessPercent,view.locale,1)} tone="green"/></div>
      {d&&<Section title={L("Prospective pedigree diversity","تنوع تبارنامه‌ای پیش‌نگر")} tone="purple"><div className="fc-metric-grid"><Metric label={L("Projected completeness","کامل‌بودن پیش‌بینی‌شده")} value={pct(d.projectedPedigreeCompletenessPercent,view.locale,1)} tone="green"/><Metric label={L("Unique recorded ancestors","نیاکان یکتای ثبت‌شده")} value={num(d.projectedUniqueRecordedAncestors,view.locale)} tone="blue"/><Metric label={L("Repeated positions","جایگاه‌های تکراری")} value={num(d.projectedRepeatedAncestorPositions,view.locale)} tone="orange"/><Metric label={L("Ancestor diversity","تنوع نیاکان")} value={pct(d.projectedAncestorDiversityPercent,view.locale,2)} tone="green"/><Metric label={L("Shared parent ancestors","نیاکان مشترک والدین")} value={num(d.sharedRecordedAncestorsBetweenParents,view.locale)} tone="purple"/><Metric label={L("Top-5 path concentration","تمرکز مسیر ۵ نیای برتر")} value={pct(d.projectedTop5RecordedPathWeightSharePercent,view.locale,2)}/><Metric label={L("Top-10 path concentration","تمرکز مسیر ۱۰ نیای برتر")} value={pct(d.projectedTop10RecordedPathWeightSharePercent,view.locale,2)}/></div><div className="fc-confidence-strip"><Badge tone={d.confidence.grade==="high"?"active":d.confidence.grade==="low"?"danger":"warning"}>{code(d.confidence.grade,view.locale)}</Badge>{d.confidence.reasons.map(reason=><small key={reason} dir="auto">{localizedAnalysisText(reason,view.locale)}</small>)}</div>{d.topProjectedAncestorContributions.length>0&&<div className="fc-table-wrap"><table className="fc-table fc-table-compact"><thead><tr><th>{L("Ancestor","نیا")}</th><th>{L("Path weight","وزن مسیر")}</th><th>{L("Share","سهم")}</th><th>{L("Parent branches","شاخه والد")}</th></tr></thead><tbody>{d.topProjectedAncestorContributions.map(a=><tr key={a.horse.id} className="fc-click-row" onClick={()=>view.navigate(horseDbRoutes.horse(a.horse.id))}><td dir="auto">{horseName(a.horse as HorseRecord,view.locale)}</td><td>{a.pathWeight.toFixed(4)}</td><td>{pct(a.shareOfRecordedPathWeightPercent,view.locale,2)}</td><td>{a.fromSire&&a.fromDam?L("Sire + dam","پدر + مادر"):a.fromSire?L("Sire","پدر"):L("Dam","مادر")}</td></tr>)}</tbody></table></div>}<p className="fc-provenance" dir="auto">{localizedAnalysisText(d.provenance.interpretation,view.locale)} · <bdi>{d.provenance.algorithmVersion}</bdi></p></Section>}
      <Section title={L("Common recorded ancestors","نیاکان مشترک ثبت‌شده")}><div className="fc-card-table">{result.commonAncestors.slice(0,30).map(a=><button key={a.horse.id} onClick={()=>view.navigate(horseDbRoutes.horse(a.horse.id))}><span><strong dir="auto">{horseName(a.horse as HorseRecord,view.locale)}</strong><small>#{a.horse.id} · {L("depths","عمق‌ها")} {a.fromDepth}/{a.toDepth}</small></span><Icon name="arrow"/></button>)}</div><p className="fc-provenance" dir="auto">{localizedAnalysisText(result.provenance.interpretation,view.locale)} · {founderAssumptionLabel(result.provenance.founderAssumption,view.locale)} · <bdi>{result.provenance.algorithmVersion}</bdi></p></Section></>}
    {result&&<ArabianPairingPanel platform={view.platform} sireId={result.sireId} damId={result.damId} locale={view.locale} principalScope={scope}/>}
    <BreedingOptimizerPanel view={view}/>
  </main>;
}

export function PlatformPage({view}:{view:ClassicRuntime}){
  const L=(en:string,fa:string)=>t(view.locale,en,fa);const catalog=Object.entries(view.platformMeta?.featureCatalog??{});const meta=view.platformMeta;
  const scalar=(obj:Record<string,unknown>|undefined)=>Object.entries(obj??{}).filter(([,value])=>value==null||["string","number","boolean"].includes(typeof value));
  const stats=meta?.stats as unknown as Record<string,unknown>|undefined;const health=meta?.health as unknown as Record<string,unknown>|undefined;const limits=meta?.limits as unknown as Record<string,unknown>|undefined;
  return <main className="fc-main"><PageTitle title={L("Platform Coverage","پوشش پلتفرم")} subtitle={L("Backend capability availability is not a guarantee of native UI coverage. Some workflows require Core or the clearly labeled synthetic demo.","قابلیت سرور به معنای پوشش کامل رابط نیست. برخی گردش‌کارها به Core یا دموی با داده ساختگی نیاز دارند.")}/>
    <Section title={L("Runtime contract & canonical provenance","قرارداد زمان اجرا و منشأ مرجع")} tone="plain"><div className="fc-platform-meta-summary"><Metric label={L("Contract","قرارداد")} value={<bdi>{meta?.contractVersion??view.platform.contractVersion}</bdi>} tone="purple"/><Metric label={L("Application","برنامه")} value={meta?.application?.shortName??meta?.application?.name??"—"} tone="blue"/><Metric label={L("Canonical horses","اسب‌های مرجع")} value={num(meta?.stats?.horses,view.locale)} tone="green"/><Metric label={L("Search rows","ردیف‌های جست‌وجو")} value={num(meta?.health?.searchRows,view.locale)} tone="orange"/></div><div className="fc-platform-meta-grid"><MetaRows title={L("Platform statistics","آمار پلتفرم")} rows={scalar(stats)} locale={view.locale}/><MetaRows title={L("Runtime health","سلامت زمان اجرا")} rows={scalar(health)} locale={view.locale}/><MetaRows title={L("Contract limits","محدودیت‌های قرارداد")} rows={scalar(limits)} locale={view.locale}/><article className="fc-platform-meta-card"><h3>{L("Canonical source provenance","منشأ منبع مرجع")}</h3>{meta?.source?<dl>{Object.entries(meta.source).map(([key,value])=><div key={key}><dt>{key}</dt><dd dir="auto">{value==null||value===""?"—":String(value)}</dd></div>)}</dl>:<p className="fc-muted">{L("Source provenance is not exposed in this environment.","منشأ منبع در این محیط ارائه نشده است.")}</p>}</article></div>{(meta?.stats as any)?.database&&<details className="fc-details"><summary>{L("Database routing state","وضعیت مسیریابی پایگاه داده")}</summary><pre className="fc-json-block">{JSON.stringify((meta?.stats as any).database,null,2)}</pre></details>}</Section>
    <Section title={L("Capability catalog","فهرست قابلیت‌ها")}><div className="fc-cap-grid">{catalog.map(([key,value])=><article key={key} className={value.available?"live":"dormant"}><header><b>{key}</b><Badge tone={value.available?"active":"dead"}>{value.available?L("LIVE","فعال"):L("DORMANT","غیرفعال")}</Badge></header><span>{value.version} · {value.stability} · {value.access}</span></article>)}</div></Section>
    <Section title={L("Canonical editorial content","محتوای تحریریه مرجع")} tone="plain"><p>{L("Published bilingual news and updates are available from the public content service. Authorized content managers can create, edit, publish and archive bilingual entries, and can use the backend-assisted draft generator when configured.","اخبار و به‌روزرسانی‌های دوزبانه منتشرشده از سرویس عمومی محتوا در دسترس‌اند. مدیران محتوای مجاز می‌توانند ورودی‌های دوزبانه را ایجاد، ویرایش، منتشر و بایگانی کنند و در صورت پیکربندی از تولید پیش‌نویس کمکی سرویس استفاده کنند.")}</p></Section>
    <Section title={L("Reserved concepts","مفاهیم رزروشده")} tone="plain"><div className="fc-dormant-list"><p><b>{L("Verification & inspections","راستی‌آزمایی و بازرسی")}</b>{L("Reserved in the current platform contract until issuer identity, evidence links and audit history are defined; Federation Classic invents no substitutes.","تا تعریف هویت صادرکننده، پیوندهای مدرک و تاریخ ممیزی در قرارداد پلتفرم رزروشده‌اند؛ Federation Classic هیچ جایگزین ساختگی ایجاد نمی‌کند.")}</p><p><b>{L("Breed standards","استانداردهای نژاد")}</b>{L("Reserved until a canonical validated source exists.","تا زمان وجود منبع مرجع معتبر رزروشده است.")}</p><p><b>{L("Genomics","ژنومیک")}</b>{L("Reserved; recorded genetic tests are laboratory results, not genomic marker analysis.","رزروشده است؛ آزمون‌های ژنتیکی ثبت‌شده نتیجه آزمایشگاهی‌اند، نه تحلیل نشانگر ژنومی.")}</p></div></Section>
    <Section title={L("Native privileged governance","حکمرانی بومی دارای دسترسی")}><p>{L("Federation Classic owns native audit, administration and curation screens. The screens are capability- and permission-gated; guests and ordinary authenticated users never probe privileged endpoints.","Federation Classic صفحه‌های بومی ممیزی، مدیریت و کیوریشن را دارد. این صفحه‌ها بر اساس قابلیت و مجوز کنترل می‌شوند؛ مهمان‌ها و کاربران عادی هرگز نقاط پایانی دارای دسترسی را فراخوانی نمی‌کنند.")}</p></Section>
  </main>;
}

function MetaRows({title,rows,locale}:{title:string;rows:Array<[string,unknown]>;locale:"en"|"fa"|"ar"}){
  return <article className="fc-platform-meta-card"><h3>{title}</h3>{rows.length?<dl>{rows.map(([key,value])=><div key={key}><dt>{key}</dt><dd dir="auto">{typeof value==="number"?num(value,locale):value==null||value===""?"—":String(value)}</dd></div>)}</dl>:<p className="fc-muted">—</p>}</article>;
}
